<?php
require_once __DIR__ . '/assert.php';
$app = require __DIR__ . '/ci3_bootstrap.php'; $db = $app->db; $app->config->set('care_team_workflow_enabled', true); $app->config->set('realtime_requests_enabled', false); $app->config->set('realtime_client_enabled', false); require_once APPPATH . 'libraries/Clinical_closure_service.php';
$db->query("CREATE TABLE IF NOT EXISTS nakes_facility_placements (placement_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,staff_id INT UNSIGNED NOT NULL,facility_code VARCHAR(64) NOT NULL,effective_from DATETIME NOT NULL,status ENUM('active','ended') NOT NULL DEFAULT 'active',active_staff_key INT UNSIGNED AS (CASE WHEN status='active' THEN staff_id ELSE NULL END) STORED,created_by_user_id INT NOT NULL,PRIMARY KEY(placement_id),UNIQUE KEY uq_nakes_active_staff(active_staff_key)) ENGINE=InnoDB");
$base = 230000 + random_int(1, 40000); $fac = 'T10A-' . $base; $actor = $base + 1; $req = $base + 10; $db->query('INSERT INTO m_puskesmas (kode_pkm,nama_puskesmas,status) VALUES (?,?,?)', array($fac, 'Task 10 Atomicity', 'aktif')); foreach (array($base - 1, $actor) as $uid) { $db->query('INSERT INTO users (userId,nama,email,username,password,role,status,must_change_password,remark) VALUES (?,?,?,?,?,?,?,?,?)', array($uid, 'T10A', 't10a' . $uid . '@invalid', 't10a' . $uid, 'x', 'dokter', 'aktif', 0, $fac)); } $db->query('INSERT INTO puskesmas_staff (staff_id,kode_pkm,user_id,nama,profesi,status) VALUES (?,?,?,?,?,?)', array($actor, $fac, $actor, 'T10A', 'dokter', 'aktif')); $db->query('INSERT INTO nakes_facility_placements (staff_id,facility_code,effective_from,status,created_by_user_id) VALUES (?,?,?,?,?)', array($actor, $fac, '2026-01-01', 'active', $actor));
$fixture=function($requestId)use($db,$actor,$fac){$db->query('INSERT INTO requests (request_id,user_id,location,request_status,assigned_puskesmas_code,assigned_puskesmas_name,consultation_mode,responsible_doctor_user_id) VALUES (?,?,?,?,?,?,?,?)',array($requestId,$actor,'x','Accepted',$fac,'Task 10 Atomicity','non_visit',$actor));$db->query('INSERT INTO request_responsible_doctor_assignments (request_id,staff_id,user_id,assigned_by_user_id,status,assigned_at) VALUES (?,?,?,?,?,NOW(6))',array($requestId,$actor,$actor,$actor,'aktif'));$db->query('INSERT INTO visit_dispositions (request_id,version_no,decision,urgency,created_by_user_id,idempotency_key,created_at) VALUES (?,?,?,?,?,?,NOW(6))',array($requestId,1,'non_visit',null,$actor,'t10a-d-'.$requestId));$db->query('INSERT INTO medicalrecords (request_id,diagnosis,treatment,recommendations,anamnesis,responsible_doctor_user_id,recorded_by_user_id,clinical_finalized_at,clinical_finalized_by_user_id) VALUES (?,?,?,?,?,?,?,NOW(6),?)',array($requestId,'d','t','r','a',$actor,$actor,$actor));};
$service = new Clinical_closure_service($db); $cases = array('clinical_closure_operations' => array('receipt', 'INSERT'), 'requests' => array('request', 'UPDATE'), 'request_events' => array('event', 'INSERT')); $n = 0; foreach ($cases as $table => $case) { $label = $case[0]; $r = $req + $n; $fixture($r); $trigger = 't10_atomic_' . $label . '_' . $base; $db->query("DROP TRIGGER IF EXISTS {$trigger}"); $created = $db->query("CREATE TRIGGER {$trigger} BEFORE {$case[1]} ON {$table} FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test failure'"); vcw_assert_true($created !== false, $label . ' trigger created'); $triggerCount = (int) $db->query("SELECT COUNT(*) AS c FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA = DATABASE() AND TRIGGER_NAME = '{$trigger}'")->row()->c; vcw_assert_same(1, $triggerCount, $label . ' trigger registered'); $result = $service->closeClinicalConsultation($r, $actor, 't10a-key-' . $r); vcw_assert_same('error', $result['status'] ?? null, $label . ' failure returns error'); vcw_assert_same('WRITE_FAILED', $result['safe_error_code'] ?? null, $label . ' safe error'); vcw_assert_same('Accepted', (string) $db->where('request_id', $r)->get('requests')->row()->request_status, $label . ' request rolled back'); vcw_assert_same(0, (int) $db->where('request_id', $r)->count_all_results('clinical_closure_operations'), $label . ' receipt rolled back'); vcw_assert_same(0, (int) $db->where('request_id', $r)->count_all_results('request_events'), $label . ' event rolled back'); $db->query("DROP TRIGGER IF EXISTS {$trigger}"); $n++; }
